#' Simulate synthetic respondents
#'
#' Draws `N` synthetic people from a scenario. For each person the propensities
#' of exposure to each vehicle are generated by the scenario, and the number of
#' contacts with vehicle `j` is `Binomial(insertions[j], propensity[j])`.
#'
#' @param scenario An object created by one of the `scenario_*()` functions.
#' @param N Number of people (a positive integer).
#' @param seed Optional single number. If given, the simulation is reproducible
#'   and the global random state is restored on exit. Reproducibility holds for
#'   a given version of R's random number generator settings.
#' @param keep_propensity If `TRUE`, the latent propensities of each person are
#'   stored in the result (default `FALSE`).
#' @param insertion_level If `TRUE`, each insertion is drawn as a 0/1 event with
#'   probability equal to the propensity of its vehicle, and the matrix is kept in
#'   `insertions`; the contacts are its row sums by vehicle. The distribution is
#'   the same as with the default, but the random stream differs. The matrix has
#'   `N` times `sum(insertions)` entries.
#' @return An object of class `mp_sim`, a list with `contacts` (an `N` by `m`
#'   integer matrix with one column per vehicle), `scenario`, `N`, `seed` and,
#'   optionally, `propensity` and `insertions` (an `N` by `sum(insertions)`
#'   integer 0/1 matrix). Use `as.data.frame()` to export it, for example
#'   with `write.csv()` for use from other languages.
#' @examples
#' scn <- scenario_gaussian(c(A = 0.2, B = 0.15), c(0.312, 0.23925), c(5, 5),
#'                          rho = 0.4)
#' sim <- simulate_exposure(scn, N = 2000, seed = 1)
#' head(sim$contacts)
#' head(as.data.frame(sim))
#' @export
simulate_exposure <- function(scenario, N, seed = NULL, keep_propensity = FALSE,
                              insertion_level = FALSE) {
  stopifnot(inherits(scenario, "mp_scenario"))
  if (length(N) != 1L || !is.finite(N) || N < 1 || N != round(N)) {
    stop("'N' must be a single positive integer.", call. = FALSE)
  }
  N <- as.integer(N)
  m <- scenario$m
  n <- scenario$insertions
  res <- .with_seed(seed, {
    pr <- switch(
      scenario$type,
      independent = vapply(seq_len(m), function(j) {
        qbeta(runif(N), scenario$alpha[j], scenario$beta[j])
      }, numeric(N)),
      gaussian = {
        z <- matrix(rnorm(N * m), N, m) %*% t(scenario$chol_factor)
        vapply(seq_len(m), function(j) .pi_from_z(scenario$alpha[j], scenario$beta[j], z[, j]),
               numeric(N))
      },
      latent_class = {
        cl <- sample.int(length(scenario$class_prob), N, replace = TRUE,
                         prob = scenario$class_prob)
        scenario$class_propensity[cl, , drop = FALSE]
      }
    )
    pr <- matrix(pr, N, m)
    ins <- NULL
    if (insertion_level) {
      col <- rep(seq_len(m), n)
      ins <- matrix(as.integer(runif(N * length(col)) < pr[, col, drop = FALSE]),
                    N, length(col))
      colnames(ins) <- paste0(rep(scenario$names, n), "_",
                              unlist(lapply(n, seq_len)))
      k <- vapply(seq_len(m), function(j) {
        rowSums(ins[, col == j, drop = FALSE])
      }, numeric(N))
      k <- matrix(as.integer(k), N, m)
    } else {
      k <- vapply(seq_len(m), function(j) rbinom(N, n[j], pr[, j]), integer(N))
    }
    list(k = matrix(k, N, m), pr = pr, ins = ins)
  })
  colnames(res$k) <- scenario$names
  out <- list(contacts = res$k, scenario = scenario, N = N, seed = seed)
  if (!is.null(res$ins)) out$insertions <- res$ins
  if (keep_propensity) {
    colnames(res$pr) <- scenario$names
    out$propensity <- res$pr
  }
  structure(out, class = "mp_sim")
}

#' Moments estimated from a simulated sample
#'
#' Estimates, from the contacts of a simulated sample, the inputs that an
#' exposure-distribution model needs: the reach of one insertion (`r1`), the
#' reach of two insertions (`r2`) and the duplication of the first insertions of
#' each pair of vehicles. The estimators use the exchangeability of the
#' insertions of a vehicle given the propensity `P`: `E[K / n] = E[P]`,
#' `E[K (K - 1)] / (n (n - 1)) = E[P^2]` and, for two vehicles,
#' `E[K_i K_j] / (n_i n_j) = E[P_i P_j]`. The reach of two insertions needs a
#' vehicle with at least two insertions; otherwise `r2` is `NA`.
#'
#' @param sim An object created by [simulate_exposure()].
#' @return A list with `r1`, `r2`, `dup` and `insertions`, as in
#'   [population_moments()].
#' @examples
#' sim <- simulate_exposure(scenario_independent(c(A = 0.2), c(0.312), 5),
#'                          N = 5000, seed = 3)
#' sample_moments(sim)
#' @export
sample_moments <- function(sim) {
  stopifnot(inherits(sim, "mp_sim"))
  k <- sim$contacts
  n <- sim$scenario$insertions
  nm <- sim$scenario$names
  x <- sweep(k, 2, n, "/")
  r1 <- colMeans(x)
  e2 <- vapply(seq_along(n), function(j) {
    if (n[j] < 2L) NA_real_ else mean(k[, j] * (k[, j] - 1)) / (n[j] * (n[j] - 1))
  }, 0)
  d <- crossprod(x) / nrow(k)
  diag(d) <- r1
  names(r1) <- nm
  r2 <- 2 * r1 - e2
  names(r2) <- nm
  list(r1 = r1, r2 = r2, dup = d, insertions = stats::setNames(n, nm))
}

#' Empirical distribution of contacts of a simulated sample
#'
#' @param sim An object created by [simulate_exposure()].
#' @return A list with `distribution` (data frame with `k`, `pmf`, `cdf`,
#'   `reach_k_plus`, over `0, ..., sum(insertions)`) and `metrics`.
#' @examples
#' sim <- simulate_exposure(scenario_independent(c(A = 0.2), c(0.312), 5),
#'                          N = 5000, seed = 3)
#' empirical_distribution(sim)$metrics$reach_1plus
#' @export
empirical_distribution <- function(sim) {
  stopifnot(inherits(sim, "mp_sim"))
  tot <- rowSums(sim$contacts)
  kmax <- sum(sim$scenario$insertions)
  pmf <- tabulate(tot + 1L, nbins = kmax + 1L) / length(tot)
  dist <- .dist_frame(pmf)
  list(distribution = dist, metrics = .dist_metrics(dist))
}

#' Error of an estimated distribution of contacts against a truth
#'
#' Compares a distribution of the total number of contacts with a reference
#' (typically [exposure_truth()]).
#'
#' @param estimate,truth Each one a numeric probability vector on
#'   `0, 1, ...`, a data frame with a `pmf` column, or an object with a
#'   `distribution` component (for example the result of
#'   [exposure_truth()] or [empirical_distribution()]). The shorter distribution
#'   is padded with zeros.
#' @return A named numeric vector: `tv` (total variation distance), `ks`
#'   (largest absolute difference of the cumulative distributions),
#'   `reach_1plus` and `reach_3plus` (estimate minus truth, as proportions), and
#'   `mean_contacts` (estimate minus truth).
#' @examples
#' scn <- scenario_independent(c(A = 0.2, B = 0.15), c(0.312, 0.23925), c(5, 5))
#' tr <- exposure_truth(scn)
#' sim <- simulate_exposure(scn, N = 5000, seed = 2)
#' distribution_error(empirical_distribution(sim), tr)
#' @export
distribution_error <- function(estimate, truth) {
  a <- .as_pmf(estimate)
  b <- .as_pmf(truth)
  len <- max(length(a), length(b))
  a <- c(a, numeric(len - length(a)))
  b <- c(b, numeric(len - length(b)))
  k <- seq_len(len) - 1L
  r3 <- function(p) if (len >= 4L) 1 - sum(p[1:3]) else NA_real_
  c(tv = 0.5 * sum(abs(a - b)), ks = max(abs(cumsum(a) - cumsum(b))),
    reach_1plus = (1 - a[1]) - (1 - b[1]), reach_3plus = r3(a) - r3(b),
    mean_contacts = sum(k * a) - sum(k * b))
}

.as_pmf <- function(x) {
  if (is.list(x) && !is.data.frame(x) && !is.null(x$distribution)) x <- x$distribution
  if (is.data.frame(x)) x <- x$pmf
  if (!is.numeric(x) || anyNA(x) || any(x < -1e-12)) {
    stop("A distribution must be a numeric vector of probabilities, a data ",
         "frame with a 'pmf' column, or an object with a 'distribution' ",
         "component.", call. = FALSE)
  }
  s <- sum(x)
  if (abs(s - 1) > 1e-6) stop("Probabilities must sum to one.", call. = FALSE)
  pmax(x, 0) / s
}

#' @export
as.data.frame.mp_sim <- function(x, row.names = NULL, optional = FALSE,
                                 level = c("vehicle", "insertion"), ...) {
  level <- match.arg(level)
  if (level == "insertion") {
    if (is.null(x$insertions)) {
      stop("No insertion-level data; use simulate_exposure(insertion_level = TRUE).",
           call. = FALSE)
    }
    df <- data.frame(id = seq_len(x$N), as.data.frame(x$insertions), check.names = FALSE)
  } else {
    df <- data.frame(id = seq_len(x$N), as.data.frame(x$contacts), check.names = FALSE)
  }
  df$total <- rowSums(x$contacts)
  if (!is.null(row.names)) rownames(df) <- row.names
  df
}

#' @export
print.mp_sim <- function(x, ...) {
  cat(sprintf("Simulated exposure (mediaPlanSim): %d people, %d vehicles, %s scenario\n",
              x$N, ncol(x$contacts), x$scenario$type))
  tot <- rowSums(x$contacts)
  cat(sprintf("Mean contacts per person: %.3f | share with 1+ contacts: %.4f\n",
              mean(tot), mean(tot > 0)))
  invisible(x)
}
